#include "game/world12/friendlies.hpp"
#include "game/world12/save.hpp"
#include "game/cup.hpp"
#include "formats/le.hpp"
#include <algorithm>
#include <limits>
#include <set>
namespace bmh::world12 {
bool friendly_appointment(const OtherAppointment& a){return a.domain==CalendarDomain::shared&&a.source_entry==0x4001;}
uint8_t friendly_source_flags(const LeImage& source){const auto at=cup_entry_address(24);if(!source.contains(at+0x27)||source.u16(at+0x18)!=10||source.u8(at+0x14)!=6)throw FormatError("world12: unsupported Source friendly descriptor");return source.u8(at+0x14);}
void initialize_friendly_plan(CareerSnapshot& snapshot,const GameState& reference){snapshot.validate();if(snapshot.friendly_plan||snapshot.date||snapshot.season||!snapshot.calendar)throw FormatError("world12: friendly initialization needs a fresh owned calendar");if(!reference.memory.has(layout::FriendlyPlanCount)||reference.memory.u8(layout::FriendlyPlanCount))throw FormatError("world12: initial Source friendly history is not empty");for(uint32_t i=0;i<30;++i)if(!reference.memory.has(layout::FriendlyDays+i*2+1)||reference.memory.u16(layout::FriendlyDays+i*2))throw FormatError("world12: initial Source friendly dates are unknown or occupied");snapshot.friendly_plan=empty_friendly_plan(0);if(snapshot.world.national_coaches){if(reference.manager_records.size()<5*0xb0c)throw FormatError("world12: Source national friendly progression is unknown");for(const auto& record:*snapshot.world.national_coaches)snapshot.friendly_plan->national_progress[record.team]=reference.manager_records[4*0xb0c+0x210];}snapshot.validate();}
void validate_friendly_plan(const CareerSnapshot& state){
    if(!state.friendly_plan){if(state.calendar&&std::any_of(state.calendar->schedule.others.begin(),state.calendar->schedule.others.end(),friendly_appointment))throw FormatError("world12: booked friendly calendar has unknown planning history");return;}
    const auto& plan=*state.friendly_plan;if(plan.season!=state.season||!plan.next_id||plan.pending.size()>30||plan.completed.size()>8192)throw FormatError("world12: invalid saved friendly plan dimensions/season");std::set<uint64_t> ids;std::set<std::pair<uint16_t,ClubId>> occupied;
    if((!plan.pending.empty()||!plan.completed.empty())&&!state.calendar)throw FormatError("world12: friendly fixtures have no actual calendar");for(const auto& [team,value]:plan.national_progress){const auto at=state.world.clubs.find(team);if(at==state.world.clubs.end()||at->second.kind!=ClubKind::national_team||(at->second.country!=Country::germany&&at->second.country!=Country::england))throw FormatError("world12: invalid friendly national progression owner");}
    const auto check=[&](const PlannedFriendly& b,bool played){const auto h=state.world.clubs.find(b.fixture.home),a=state.world.clubs.find(b.fixture.away);if(!b.id||b.id>=plan.next_id||!ids.insert(b.id).second||b.day>=366||b.fixture.home==b.fixture.away||h==state.world.clubs.end()||a==state.world.clubs.end()||b.national!=(h->second.kind==ClubKind::national_team)||b.national!=(a->second.kind==ClubKind::national_team)||(b.payer&&std::none_of(state.world.managers.begin(),state.world.managers.end(),[&](const auto& m){return m.seat==*b.payer;}))||(!b.payer&&b.cost))throw FormatError("world12: invalid actual friendly identity/receipt");if(!b.national&&(!state.world.catalogue.scope.club_play()||!h->second.league.valid()||!a->second.league.valid()))throw FormatError("world12: friendly club roster scope is unavailable");if(!occupied.insert({b.day,b.fixture.home}).second||!occupied.insert({b.day,b.fixture.away}).second)throw FormatError("world12: friendly date repeats a participant");if(state.calendar){if(b.day>=state.calendar->schedule.days||played!=(b.day<state.calendar->next_day))throw FormatError("world12: friendly result/date disagrees with saved clock");const auto matching=std::count_if(state.calendar->schedule.others.begin(),state.calendar->schedule.others.end(),[&](const auto& appointment){return appointment.day==b.day&&friendly_appointment(appointment);});if(matching!=1)throw FormatError("world12: actual friendly has no unique calendar owner");}};
    uint16_t previous=0;for(const auto& b:plan.pending){check(b,false);if(b.day<previous)throw FormatError("world12: friendly pending dates are unordered");previous=b.day;}
    for(const auto& b:plan.completed){check(b.booking,true);if(b.score==0xcccc||b.end_minute<90||b.end_minute>94)throw FormatError("world12: friendly has no actual full-time result");}
    if(state.calendar)for(const auto& appointment:state.calendar->schedule.others)if(friendly_appointment(appointment)){bool found=false;for(const auto& b:plan.pending)found|=b.day==appointment.day;for(const auto& b:plan.completed)found|=b.booking.day==appointment.day;if(!found)throw FormatError("world12: friendly calendar marker has no real booking");}
}
std::vector<FriendlyGroup> prepare_friendly_groups(const CareerSnapshot& state){std::vector<FriendlyGroup> groups;if(!state.calendar)return groups;const auto day=state.calendar->next_day;const auto appointments=state.calendar->schedule.others_on(day);if(std::none_of(appointments.begin(),appointments.end(),friendly_appointment))return groups;if(!state.friendly_plan)throw FormatError("world12: current friendly plan is unknown");for(const auto& booking:state.friendly_plan->pending)if(booking.day==day){if(groups.empty())groups.push_back({state.season,day,state.friendly_plan->revision,booking.national,6,{},{}});if(groups.front().national!=booking.national)throw FormatError("world12: national and club friendlies cannot share a role window");groups.front().bookings.push_back(booking.id);groups.front().matches.push_back(booking.fixture);}if(groups.empty())throw FormatError("world12: friendly date has no pending fixture");return groups;}
void commit_friendly_results(CareerSnapshot& state,const std::vector<FriendlyResults>& results){const auto expected=prepare_friendly_groups(state);if(results.size()!=expected.size())throw FormatError("world12: complete friendly results are required");if(results.empty())return;if(state.friendly_plan->revision==std::numeric_limits<uint64_t>::max())throw FormatError("world12: friendly revision exhausted");for(size_t g=0;g<results.size();++g){const auto& r=results[g];if(r.group!=expected[g]||r.scores.size()!=r.group.matches.size()||r.end_minutes.size()!=r.scores.size())throw FormatError("world12: stale/incomplete friendly result batch");for(size_t m=0;m<r.scores.size();++m)if(r.scores[m]==0xcccc||r.end_minutes[m]<90||r.end_minutes[m]>94)throw FormatError("world12: friendly result has no actual full-time receipt");}
    for(const auto& r:results)for(size_t n=0;n<r.group.bookings.size();++n){const auto at=std::find_if(state.friendly_plan->pending.begin(),state.friendly_plan->pending.end(),[&](const auto& b){return b.id==r.group.bookings[n];});if(at==state.friendly_plan->pending.end())throw FormatError("world12: friendly booking disappeared");state.friendly_plan->completed.push_back({*at,r.scores[n],r.end_minutes[n]});state.friendly_plan->pending.erase(at);}++state.friendly_plan->revision;
}
}
